use std::collections::HashSet;

fn is_in_array(a: &[i32], x: i32) -> bool {
    a.iter().any(|&item| item == x)
}

fn contains(v: &Vec<i32>, x: i32) -> bool {
    v.iter().any(|&item| item == x)
}

fn remove_elements(a: &[i32], b: &[i32]) -> Vec<i32> {
    let b_set: HashSet<i32> = b.iter().cloned().collect(); // Create a HashSet from the second slice
    let mut result_set: HashSet<i32> = HashSet::new(); // To store unique results

    for &item in a {
        if !b_set.contains(&item) { // Check if item is not in the second slice
            result_set.insert(item); // Insert into the result set to avoid duplicates
        }
    }

    result_set.into_iter().collect() // Convert the HashSet back to a Vec<i32>
}

// Example usage
fn main() {
    let a = [1, 2, 3, 4, 5, 2, 3];
    let b = [3, 4, 5];
    let result = remove_elements(&a, &b);
    println!("{:?}", result); // Output could be [1, 2] or [2, 1] depending on the order of insertion
}